{
  "wire_schema": "role_benchmark.player_action",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H_newton_exp",
        "statement": "Object temperature follows Newton's law of cooling: T(t)=Ta+(T0-Ta)*exp(-k t), with constant k over the tested range.",
        "confidence": 0.6
      },
      {
        "hypothesis_id": "H_linear",
        "statement": "Object temperature decreases linearly toward ambient at a constant rate until reaching ambient: T(t)=max(Ta, T0-r t).",
        "confidence": 0.25
      },
      {
        "hypothesis_id": "H_inverse",
        "statement": "Temperature excess decays inversely with time: T(t)=Ta+(T0-Ta)/(1+k t).",
        "confidence": 0.15
      }
    ]
  },
  "experiment": {
    "intent": "Measure the cooling curve at several times for T0=90 and Ta=20 to distinguish exponential, linear, and inverse decay of the temperature excess.",
    "apparatus": "controlled_cooling_chamber",
    "controls": {
      "initial_temperature_c": 90.0,
      "ambient_temperature_c": 20.0,
      "elapsed_time_min": 5.0
    },
    "readouts": [
      "object_temperature_c"
    ],
    "replicates": 1,
    "forecasts": {
      "H_newton_exp": {
        "object_temperature_c": 68.0
      },
      "H_linear": {
        "object_temperature_c": 76.0
      },
      "H_inverse": {
        "object_temperature_c": 63.3
      }
    }
  },
  "final": null
}

